{
  "assessment": "Our economy remains crippled by hyperinflation at 247.3% and an unsustainable fiscal deficit of 18.4% of GDP, with debt at the absolute borrowing limit. Although public mood is calm and support across sectors is stable, economic stabilization is our most urgent priority to prevent a debt default and social collapse. We must accept Cuba's trade proposal to solidify regional solidarity, maintain tight monetary policy to combat inflation, and carefully balance our budget.",
  "directives": [
    {
      "type": "trade_deal_accept",
      "target": "CUB",
      "amount": 0,
      "sub": "",
      "order": "Accept the trade deal proposed by Cuba to strengthen economic and energy ties."
    },
    {
      "type": "monetary_policy",
      "target": null,
      "amount": 1.0,
      "sub": "",
      "order": "Raise the policy rate further to cool down hyperinflation."
    },
    {
      "type": "set_tax",
      "target": null,
      "amount": 60.0,
      "sub": "",
      "order": "Adjust total revenue target to 60 percent of GDP to address the massive fiscal deficit."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 2.0,
      "sub": "health",
      "order": "Maintain health spending at sustainable levels."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 8.0,
      "sub": "welfare",
      "order": "Rationalise welfare spending to comply with debt limits."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 1.5,
      "sub": "military",
      "order": "Keep military spending constrained at 1.5 percent of GDP."
    }
  ],
  "cables": [
    {
      "to": "CUB",
      "private": true,
      "text": "Caracas accepts your proposal for a strategic economic and energy partnership with great enthusiasm. Long live our solidarity."
    }
  ],
  "public_statement": "The Bolivarian Republic of Venezuela remains steadfast in its commitment to economic sovereignty, national dignity, and deepening fraternal ties with our socialist allies across the world in the face of imperialist pressure.",
  "standing_orders": [
    {
      "when": "inflation_above:100",
      "do": {
        "type": "monetary_policy",
        "target": null,
        "amount": 0.5,
        "sub": "",
        "order": "Tighten monetary policy to combat inflation."
      }
    }
  ],
  "detailed_report": "economy"
}
